// Shared handler for the load-handwritten-lessons functions.
// Loads the hand-written lessons (days 6-30, tag handwritten-v1) into public.stacks and public.slides.
//
// The lessons are bundled in ./data (generated by scripts/lessons/export_loader.py from scripts/lessons/<market>/,
// the same rows as the drizzle/migrations/00NN_<market>_handwritten_days_6_30.sql files), so loading them needs
// no SQL pasting: deploy each function, then call each once.
//
//   GET  -> what would change, per market (writes nothing)
//   POST -> upserts every stack that is missing or whose content changed and replaces its slides,
//           then checks that every bundled day holds one stack per learner goal
//
// It needs no sign-in on purpose: it can only write the lessons bundled with it, and only stacks whose content
// fingerprint (stacks.metadata.handwritten_src) differs, so a second call writes nothing.
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { batches, dayProblems, slideRecords, stackRecord, stacksToWrite, type LessonStack, type StoredStack } from "./handwritten-plan.ts";

/** Serves one loader for the markets bundled with it (each load-handwritten-lessons[-N] function bundles a share). */
export function serveHandwrittenLoader(LESSONS: Record<string, unknown[]>) {
  const corsHeaders = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  };
  const json = (body: unknown, status = 200) =>
    new Response(JSON.stringify(body, null, 2), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  Deno.serve(async (req) => {
    if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
    if (req.method !== "GET" && req.method !== "POST") return json({ error: "Use GET to preview or POST to load." }, 405);

    try {
      const db = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
      const write = req.method === "POST";

      const storedStacks = async (ids: string[]): Promise<{ rows: StoredStack[]; error?: string }> => {
        const rows: StoredStack[] = [];
        for (const chunk of batches(ids, 100)) {
          const { data, error } = await db.from("stacks").select("id, metadata, published_at").in("id", chunk);
          if (error) return { rows, error: error.message };
          rows.push(...((data ?? []) as StoredStack[]));
        }
        return { rows };
      };

      const report: Record<string, { bundled: number; written: number; alreadyCurrent: number }> = {};
      for (const [market, bundledRows] of Object.entries(LESSONS)) {
        const bundled = bundledRows as LessonStack[];
        const { rows: stored, error } = await storedStacks(bundled.map(row => row.id));
        if (error) return json({ error: `${market}: ${error}`, report }, 500);
        const pending = stacksToWrite(bundled, stored);
        if (write) {
          const byId = new Map(stored.map(row => [row.id, row]));
          const now = new Date().toISOString();
          for (const batch of batches(pending)) {
            const { error: upsertError } = await db
              .from("stacks")
              .upsert(batch.map(row => stackRecord(row, byId.get(row.id), now)), { onConflict: "id" });
            if (upsertError) return json({ error: `${market} stacks: ${upsertError.message}`, report }, 500);
            const ids = batch.map(row => row.id);
            const { error: deleteError } = await db.from("slides").delete().in("stack_id", ids);
            if (deleteError) return json({ error: `${market} slides: ${deleteError.message}`, report }, 500);
            const { error: insertError } = await db.from("slides").insert(batch.flatMap(slideRecords));
            if (insertError) return json({ error: `${market} slides: ${insertError.message}`, report }, 500);
          }
        }
        report[market] = { bundled: bundled.length, written: write ? pending.length : 0, alreadyCurrent: bundled.length - pending.length };
      }

      // Every bundled day should hold one hand-written stack per learner goal.
      const all: { market_id: string; tags: string[] | null }[] = [];
      for (const [market, bundledRows] of Object.entries(LESSONS)) {
        const days = new Set((bundledRows as LessonStack[]).map(row => row.tags.find(t => /^day-\d+$/.test(t))));
        const { data, error } = await db.from("stacks").select("market_id, tags")
          .eq("market_id", market).contains("tags", ["handwritten-v1"]).limit(1000);
        if (error) return json({ error: `${market}: ${error.message}`, report }, 500);
        all.push(...((data ?? []) as { market_id: string; tags: string[] | null }[])
          .filter(row => days.has((row.tags ?? []).find(t => /^day-\d+$/.test(t)))));
      }
      const totals: Record<string, number> = {};
      for (const row of all) totals[row.market_id] = (totals[row.market_id] ?? 0) + 1;

      return json({
        mode: write ? "loaded" : "preview (POST to load)",
        report,
        handwrittenStacksInDatabase: totals,
        daysWithoutFourStacks: dayProblems(all),
      });
    } catch (err) {
      return json({ error: err instanceof Error ? err.message : String(err) }, 500);
    }
  });
}
